import ipaddress

def decouper(reseau, prefixe, n):
    sous_reseaux = ipaddress.ip_network(reseau).subnets(new_prefix=prefixe)
    resultat = []
    for i, s in enumerate(sous_reseaux):
        if i == n:
            break
        resultat.append(str(s))
    return resultat

print(decouper("10.0.0.0/16", 24, 3))

