def action(methode, chemin):
    morceaux = chemin.strip("/").split("/")
    if not morceaux or morceaux[0] != "clients" or len(morceaux) > 2:
        return "inconnu"
    if len(morceaux) == 1:
        return {"GET": "lister", "POST": "créer"}.get(methode, "inconnu")
    ident = morceaux[1]
    verbe = {"GET": "lire", "PATCH": "modifier", "DELETE": "supprimer"}.get(methode)
    return f"{verbe} {ident}" if verbe else "inconnu"

print(action("GET", "/clients/42"))
